// === FILTRA EVENTOS CHATWOOT ===
// So processa: message_created por humano (sender.type=user, message_type=outgoing)
// Ignora: msgs da Bia (syncadas pelo n8n), msgs incoming, status changes, etc.

const payload = $input.first().json.body || $input.first().json;
const event = payload.event || '';

// Processa: message_created (humano respondendo) ou conversation_status_changed (resolver → devolver pra Bia)
if (event === 'conversation_status_changed') {
  // Conversa resolvida = devolver pra Bia (resetar is_human_takeover)
  const conv = payload.conversation || payload;
  const status = conv.status || payload.status;
  if (status === 'resolved') {
    const contact = conv.contact || conv.meta?.sender || {};
    const phone = (contact.phone_number || contact.identifier || '').replace(/[^0-9]/g, '');
    return [{ json: {
      _skip: false,
      _action: 'reset_handoff',
      phone: phone,
      conversation_id: conv.id,
      contact_id: contact.id
    } }];
  }
  return [{ json: { _skip: true, reason: 'status_not_resolved', status } }];
}

if (event !== 'message_created') {
  return [{ json: { _skip: true, reason: 'unhandled_event', event } }];
}

const message = payload.message || payload;
const conversation = payload.conversation || {};
const sender = message.sender || {};
const account = payload.account || {};

// FILTRO 1: So mensagens outgoing (humano respondendo)
if (message.message_type !== 1 && message.message_type !== 'outgoing') {
  return [{ json: { _skip: true, reason: 'not_outgoing', message_type: message.message_type } }];
}

// FILTRO 2: So de agentes humanos (sender.type = 'user' no Chatwoot)
// sender.type = 'user' = agente humano
// sender.type = 'agent_bot' ou 'contact' = nao humano
if (sender.type !== 'user') {
  return [{ json: { _skip: true, reason: 'not_human_sender', sender_type: sender.type } }];
}

// FILTRO 2.5: Anti-loop — mensagens syncadas pelo n8n tem \u200B no final
const msgContent = (message.content || '');
if (msgContent.endsWith('\u200B') || msgContent.endsWith('\u200b')) {
  return [{ json: { _skip: true, reason: 'n8n_synced_zwsp' } }];
}

// FILTRO 3: Anti-loop — so encaminha se humano esta atendendo (is_human_takeover=true)
// Se is_human_takeover=false, a Bia ta atendendo e essa msg e sync do Sender → ignorar
const https = require('https');
const _conv = payload.conversation || {};
const _contact = _conv.contact || _conv.meta?.sender || {};
const phoneForCheck = (_contact.phone_number || _contact.identifier || '').replace(/[^0-9]/g, '');
if (phoneForCheck) {
  try {
    const checkResult = await new Promise((resolve, reject) => {
      const req = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phoneForCheck + '&select=is_human_takeover',
        method: 'GET',
        headers: {
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}'
        }
      }, (res) => {
        let data = '';
        res.on('data', c => data += c);
        res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve([]); } });
      });
      req.on('error', () => resolve([]));
      req.end();
    });
    const isHumanActive = checkResult?.[0]?.is_human_takeover === true;
    if (!isHumanActive) {
      // Humano digitou no Chatwoot sem handoff prévio — setar is_human_takeover=true
      try {
        await new Promise((resolve, reject) => {
          const body = JSON.stringify({ is_human_takeover: true });
          const req = https.request({
            hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
            path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phoneForCheck,
            method: 'PATCH',
            headers: {
              'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
              'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
              'Content-Type': 'application/json',
              'Content-Length': Buffer.byteLength(body)
            }
          }, (res) => { let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(d)); });
          req.on('error', () => resolve(''));
          req.write(body);
          req.end();
        });
      } catch (e) { /* best effort */ }
    }
  } catch (e) {
    // If check fails, let it through (safe fallback)
  }
}

// FILTRO 3 original: Anti-loop — ignora msgs com content_attributes.external
// O n8n seta esse atributo quando synca msgs pro Chatwoot
const contentAttrs = message.content_attributes || {};
if (contentAttrs.external === true || contentAttrs.synced_by === 'n8n') {
  return [{ json: { _skip: true, reason: 'synced_by_n8n' } }];
}

// FILTRO 4: Ignora msgs privadas (notas internas)
if (message.private === true) {
  return [{ json: { _skip: true, reason: 'private_note' } }];
}

// Extrai dados
const contact = conversation.contact || conversation.meta?.sender || {};
const phone = contact.phone_number || contact.identifier || '';
const phoneClean = phone.replace(/[^0-9]/g, '');

return [{ json: {
  _skip: false,
  text: message.content || '',
  phone: phoneClean,
  conversation_id: conversation.id || message.conversation_id,
  contact_id: contact.id,
  sender_name: sender.name || 'Agente',
  message_id: message.id
} }];

// Handle reset_handoff action (conversa resolvida no Chatwoot → devolver pra Bia)
if ($input.first().json._action === 'reset_handoff') {
  const https = require('https');
  const phone = $input.first().json.phone;
  const body = JSON.stringify({ is_human_takeover: false });
  const options = {
    hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
    path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phone,
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
      'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
      'Content-Length': Buffer.byteLength(body)
    },
    timeout: 5000
  };
  await new Promise((resolve) => {
    const r = https.request(options, () => resolve());
    r.on('error', () => resolve());
    r.write(body);
    r.end();
  });
  return [{ json: { status: 'handoff_reset', phone } }];
}

// === RESOLVE PHONE NUMBER ID ===
// Busca o phone_number_id do contato no Supabase
// pra saber pra qual conta Cloud API enviar

const https = require('https');
const input = $input.first().json;

const SB_URL = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SB_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

const phone = input.phone;
if (!phone) return [{ json: { ...input, phone_number_id: null, _error: 'no_phone' } }];

const data = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: SB_URL,
    path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phone + '&select=phone_number_id',
    method: 'GET',
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY },
    timeout: 5000
  }, (res) => {
    let d = '';
    res.on('data', c => d += c);
    res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve(null); } });
  });
  req.on('error', () => resolve(null));
  req.end();
});

const phone_number_id = (data && data.length > 0) ? data[0].phone_number_id : '717596344764478'; // Default: conta 07

return [{ json: { ...input, phone_number_id } }];

// === ENVIA VIA CLOUD API ===
// Humano respondeu no Chatwoot → envia pro WhatsApp do lead via Cloud API

const https = require('https');
const input = $input.first().json;

const TOKEN_BY_PHONE = {
  '{{PHONE_NUMBER_ID}}': '{{SYSTEM_USER_TOKEN}}',
  // '<phone_number_id_2>': '<system_user_token_2>',  // numero de outra BM
};
const phone_number_id = input.phone_number_id;
const CLOUD_API_TOKEN = TOKEN_BY_PHONE[phone_number_id] || '{{SYSTEM_USER_TOKEN}}';
const recipient = input.phone;
const text = input.text;

if (!phone_number_id || !recipient || !text) {
  // Save human message to bia_agent_context so Bia has context when she returns
  try {
    // Get current agent_id for this contact
    const ctxGet = await new Promise((resolve) => {
      const req = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + recipient + '&select=active_agent_id',
        method: 'GET',
        headers: {
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}'
        }
      }, (res) => {
        let d = ''; res.on('data', c => d += c);
        res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve([]); } });
      });
      req.on('error', () => resolve([]));
      req.end();
    });
    const agentId = ctxGet?.[0]?.active_agent_id || 'bia';

    // Append human message to context via Supabase RPC
    const ctxBody = JSON.stringify({
      p_subscriber_id: String(recipient),
      p_agent_id: agentId,
      p_role: 'assistant',
      p_content: '[HUMANO - ' + (input.sender_name || 'Agente') + '] ' + text
    });
    await new Promise((resolve) => {
      const req = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/rpc/append_agent_context',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
          'Content-Length': Buffer.byteLength(ctxBody)
        }
      }, () => resolve());
      req.on('error', () => resolve());
      req.write(ctxBody);
      req.end();
    });
  } catch (e) { /* best effort — context save is non-blocking */ }

  return [{ json: { status: 'error', error: 'Missing data', phone_number_id, recipient, text: !!text } }];
}

const res = await new Promise((resolve, reject) => {
  const body = JSON.stringify({
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: recipient,
    type: 'text',
    text: { preview_url: true, body: text }
  });
  const options = {
    hostname: 'graph.facebook.com',
    path: '/v21.0/' + phone_number_id + '/messages',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + CLOUD_API_TOKEN,
      'Content-Length': Buffer.byteLength(body)
    },
    timeout: 10000
  };
  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', c => data += c);
    res.on('end', () => {
      try { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, data: JSON.parse(data) }); }
      catch { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, data: { raw: data } }); }
    });
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

console.log(JSON.stringify({
  event: 'chatwoot_human_send',
  phone: recipient,
  phone_number_id,
  sender: input.sender_name,
  status: res.ok ? 'sent' : 'error',
  timestamp: new Date().toISOString()
}));


  // Setar is_human_takeover=true (humano respondendo via Chatwoot → Bia nao responde por cima)
  try {
    const hBody = JSON.stringify({ is_human_takeover: true });
    await new Promise((resolve) => {
      const hReq = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + recipient,
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
          'Content-Length': Buffer.byteLength(hBody)
        },
        timeout: 5000
      }, () => resolve());
      hReq.on('error', () => resolve());
      hReq.write(hBody);
      hReq.end();
    });
  } catch (e) { /* best effort */ }

  // Save human message to bia_agent_context so Bia has context when she returns
  try {
    // Get current agent_id for this contact
    const ctxGet = await new Promise((resolve) => {
      const req = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + recipient + '&select=active_agent_id',
        method: 'GET',
        headers: {
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}'
        }
      }, (res) => {
        let d = ''; res.on('data', c => d += c);
        res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve([]); } });
      });
      req.on('error', () => resolve([]));
      req.end();
    });
    const agentId = ctxGet?.[0]?.active_agent_id || 'bia';

    // Append human message to context via Supabase RPC
    const ctxBody = JSON.stringify({
      p_subscriber_id: String(recipient),
      p_agent_id: agentId,
      p_role: 'assistant',
      p_content: '[HUMANO - ' + (input.sender_name || 'Agente') + '] ' + text
    });
    await new Promise((resolve) => {
      const req = https.request({
        hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
        path: '/rest/v1/rpc/append_agent_context',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
          'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
          'Content-Length': Buffer.byteLength(ctxBody)
        }
      }, () => resolve());
      req.on('error', () => resolve());
      req.write(ctxBody);
      req.end();
    });
  } catch (e) { /* best effort — context save is non-blocking */ }

  return [{ json: {
  status: res.ok ? 'sent' : 'error',
  phone: recipient,
  sender: input.sender_name,
  message_preview: text.substring(0, 80),
  cloud_api_response: res.data
} }];
